insert into public.questions (exam_id, year, subject_id, topic_id, difficulty, question_en, question_hi, options, correct_option, solution_en, solution_hi, is_dropped, is_high_priority, theme, source, created_by)
select e.id, 2015, s.id, t.id, 'easy', 'Who was the founder of the Mauryan Empire?', 'मौर्य साम्राज्य का संस्थापक कौन था?', '[{"key":"A","en":"Bindusara","hi":"बिंदुसार"},{"key":"B","en":"Chandragupta Maurya","hi":"चंद्रगुप्त मौर्य"},{"key":"C","en":"Ashoka","hi":"अशोक"},{"key":"D","en":"Bimbisara","hi":"बिंबिसार"}]'::jsonb, 'B', '<p><b>Correct: (B) Chandragupta Maurya</b> — with the guidance of Chanakya (Kautilya) he overthrew the Nanda dynasty around 322 BCE and founded the Mauryan Empire with Pataliputra as capital.</p><p>(A) Bindusara was his son and successor. (C) Ashoka was Bindusara''s son, the third Mauryan ruler. (D) Bimbisara belonged to the earlier Haryanka dynasty of Magadha.</p>', '<p><b>सही उत्तर: (B) चंद्रगुप्त मौर्य</b> — चाणक्य (कौटिल्य) के मार्गदर्शन में लगभग 322 ई.पू. में नंद वंश को हराकर उन्होंने मौर्य साम्राज्य की स्थापना की; राजधानी पाटलिपुत्र थी।</p><p>(A) बिंदुसार उनके पुत्र व उत्तराधिकारी थे। (C) अशोक बिंदुसार के पुत्र और तीसरे मौर्य शासक थे। (D) बिंबिसार इससे पहले के हर्यक वंश के शासक थे।</p>', false, false, 'magadha-empire', 'sample', null
from public.subjects s join public.topics t on t.subject_id = s.id and t.slug = 'ancient'
