select e.id, 2018, s.id, t.id, 'medium', 'Nalanda Mahavihara was founded by which Gupta ruler?', 'नालंदा महाविहार की स्थापना किस गुप्त शासक ने की थी?', '[{"key":"A","en":"Kumaragupta I","hi":"कुमारगुप्त प्रथम"},{"key":"B","en":"Chandragupta II","hi":"चंद्रगुप्त द्वितीय"},{"key":"C","en":"Samudragupta","hi":"समुद्रगुप्त"},{"key":"D","en":"Skandagupta","hi":"स्कंदगुप्त"}]'::jsonb, 'A', '<p><b>Correct: (A) Kumaragupta I</b> (c. 415–455 CE) is credited with founding Nalanda Mahavihara; it later received patronage from Harshavardhana and the Pala kings.</p><p>(B) Chandragupta II ''Vikramaditya'' is known for Kalidasa and Fa-Hien''s visit. (C) Samudragupta is known for the Allahabad (Prayag) Prashasti. (D) Skandagupta is known for repelling the Hunas.</p>', '<p><b>सही उत्तर: (A) कुमारगुप्त प्रथम</b> (लगभग 415–455 ई.) को नालंदा महाविहार की स्थापना का श्रेय दिया जाता है; बाद में हर्षवर्धन व पाल शासकों ने इसे संरक्षण दिया।</p><p>(B) चंद्रगुप्त द्वितीय ''विक्रमादित्य'' कालिदास और फाह्यान की यात्रा के लिए प्रसिद्ध हैं। (C) समुद्रगुप्त प्रयाग प्रशस्ति के लिए जाने जाते हैं। (D) स्कंदगुप्त ने हूणों को पराजित किया था।</p>', false, false, 'nalanda', 'sample', null
from public.subjects s join public.topics t on t.subject_id = s.id and t.slug = 'ancient'
