select e.id, 2020, s.id, t.id, 'medium', 'Pataliputra was made the capital of Magadha by which ruler?', 'पाटलिपुत्र को मगध की राजधानी किस शासक ने बनाया?', '[{"key":"A","en":"Bimbisara","hi":"बिंबिसार"},{"key":"B","en":"Ajatashatru","hi":"अजातशत्रु"},{"key":"C","en":"Udayin","hi":"उदयिन"},{"key":"D","en":"Shishunaga","hi":"शिशुनाग"}]'::jsonb, 'C', '<p><b>Correct: (C) Udayin</b> (Udayabhadra), son of Ajatashatru, founded the city at the confluence of the Ganga and Son and shifted the capital from Rajgriha to Pataliputra.</p><p>(A) Bimbisara ruled from Rajgriha (Girivraj). (B) Ajatashatru built a fort at Pataligrama, but did not shift the capital. (D) Shishunaga temporarily shifted the capital to Vaishali.</p>', '<p><b>सही उत्तर: (C) उदयिन</b> (उदयभद्र), अजातशत्रु के पुत्र, ने गंगा–सोन संगम पर नगर बसाया और राजधानी राजगृह से पाटलिपुत्र स्थानांतरित की।</p><p>(A) बिंबिसार की राजधानी राजगृह (गिरिव्रज) थी। (B) अजातशत्रु ने पाटलिग्राम में दुर्ग बनवाया, पर राजधानी नहीं बदली। (D) शिशुनाग ने अस्थायी रूप से राजधानी वैशाली स्थानांतरित की।</p>', false, false, 'magadha-empire', 'sample', null
from public.subjects s join public.topics t on t.subject_id = s.id and t.slug = 'bihar-history'
