where s.slug = 'history';
insert into public.questions (exam_id, year, subject_id, topic_id, difficulty, question_en, question_hi, options, correct_option, solution_en, solution_hi, is_dropped, is_high_priority, theme, source, created_by)
select e.id, 2017, s.id, t.id, 'easy', 'The tomb of Sher Shah Suri is located at:', 'शेरशाह सूरी का मकबरा कहाँ स्थित है?', '[{"key":"A","en":"Sasaram","hi":"सासाराम"},{"key":"B","en":"Delhi","hi":"दिल्ली"},{"key":"C","en":"Agra","hi":"आगरा"},{"key":"D","en":"Chunar","hi":"चुनार"}]'::jsonb, 'A', '<p><b>Correct: (A) Sasaram</b> (Rohtas district, Bihar). The red-sandstone tomb stands in the middle of an artificial lake and is a fine example of Indo-Afghan architecture.</p><p>Delhi, Agra and Chunar are associated with Sher Shah''s campaigns and buildings (e.g. Purana Qila in Delhi), but his tomb is in his birthplace region, Sasaram.</p>', '<p><b>सही उत्तर: (A) सासाराम</b> (रोहतास ज़िला, बिहार)। लाल बलुआ पत्थर से बना यह मकबरा कृत्रिम झील के बीच स्थित है और इंडो-अफ़गान स्थापत्य का उत्कृष्ट उदाहरण है।</p><p>दिल्ली, आगरा और चुनार शेरशाह के अभियानों/निर्माणों (जैसे दिल्ली का पुराना किला) से जुड़े हैं, पर उनका मकबरा सासाराम में है।</p>', false, false, 'sher-shah', 'sample', null
from public.subjects s join public.topics t on t.subject_id = s.id and t.slug = 'medieval'
left join public.exams e on e.short_name = '60-62nd'
where s.slug = 'history';
insert into public.questions (exam_id, year, subject_id, topic_id, difficulty, question_en, question_hi, options, correct_option, solution_en, solution_hi, is_dropped, is_high_priority, theme, source, created_by)
select e.id, 2017, s.id, t.id, 'easy', 'Who persuaded Mahatma Gandhi to come to Champaran in 1917?', '1917 में महात्मा गांधी को चंपारण आने के लिए किसने प्रेरित किया?', '[{"key":"A","en":"Rajkumar Shukla","hi":"राजकुमार शुक्ल"},{"key":"B","en":"Dr. Rajendra Prasad","hi":"डॉ. राजेंद्र प्रसाद"},{"key":"C","en":"Brajkishore Prasad","hi":"ब्रजकिशोर प्रसाद"},{"key":"D","en":"Anugrah Narayan Sinha","hi":"अनुग्रह नारायण सिन्हा"}]'::jsonb, 'A', '<p><b>Correct: (A) Rajkumar Shukla</b>, an indigo cultivator of Champaran, met Gandhi at the Lucknow Congress (1916) and persuaded him to see the plight of farmers under the <i>tinkathia</i> system.</p><p>(B), (C) and (D) joined Gandhi during the Champaran Satyagraha as associates, but did not invite him.</p>', '<p><b>सही उत्तर: (A) राजकुमार शुक्ल</b> — चंपारण के नील किसान, जिन्होंने लखनऊ कांग्रेस (1916) में गांधीजी से मिलकर उन्हें <i>तिनकठिया</i> प्रथा से पीड़ित किसानों की दशा देखने के लिए राज़ी किया।</p><p>(B), (C) व (D) चंपारण सत्याग्रह में गांधीजी के सहयोगी बने, पर आमंत्रण उन्होंने नहीं दिया।</p>', false, false, 'champaran', 'sample', null
from public.subjects s join public.topics t on t.subject_id = s.id and t.slug = 'modern'
left join public.exams e on e.short_name = '63rd'
where s.slug = 'history';
insert into public.questions (exam_id, year, subject_id, topic_id, difficulty, question_en, question_hi, options, correct_option, solution_en, solution_hi, is_dropped, is_high_priority, theme, source, created_by)
select e.id, 2019, s.id, t.id, 'easy', 'Who led the Revolt of 1857 from Jagdishpur in Bihar?', '1857 के विद्रोह में बिहार के जगदीशपुर से नेतृत्व किसने किया?', '[{"key":"A","en":"Kunwar Singh","hi":"कुँवर सिंह"},{"key":"B","en":"Pir Ali","hi":"पीर अली"},{"key":"C","en":"Waris Ali","hi":"वारिस अली"},{"key":"D","en":"Jitu Santhal","hi":"जीतू संथाल"}]'::jsonb, 'A', '<p><b>Correct: (A) Babu Kunwar Singh</b>, the zamindar of Jagdishpur (Bhojpur), led the revolt in Bihar at about 80 years of age; 23 April is observed as ''Vijayotsav''.</p><p>(B) Pir Ali led the uprising in Patna and was hanged in July 1857. (C) Waris Ali was a police jamadar in Tirhut, among the first executed in Bihar. (D) is not associated with leading 1857 in Jagdishpur.</p>', '<p><b>सही उत्तर: (A) बाबू कुँवर सिंह</b>, जगदीशपुर (भोजपुर) के ज़मींदार, ने लगभग 80 वर्ष की आयु में बिहार में विद्रोह का नेतृत्व किया; 23 अप्रैल ''विजयोत्सव'' के रूप में मनाया जाता है।</p><p>(B) पीर अली ने पटना में विद्रोह किया और जुलाई 1857 में फाँसी दी गई। (C) वारिस अली तिरहुत के पुलिस जमादार थे। (D) का जगदीशपुर के नेतृत्व से संबंध नहीं है।</p>', false, false, '1857-bihar', 'sample', null
from public.subjects s join public.topics t on t.subject_id = s.id and t.slug = 'bihar-history'
left join public.exams e on e.short_name = '65th'
where s.slug = 'history';
insert into public.questions (exam_id, year, subject_id, topic_id, difficulty, question_en, question_hi, options, correct_option, solution_en, solution_hi, is_dropped, is_high_priority, theme, source, created_by)
select e.id, 2023, s.id, t.id, 'medium', '<p>Match List-I (Newspaper) with List-II (Founder/Editor):</p><table><tr><th>List-I</th><th>List-II</th></tr><tr><td>(a) Kesari</td><td>1. Surendranath Banerjee</td></tr><tr><td>(b) Harijan</td><td>2. Maulana Abul Kalam Azad</td></tr><tr><td>(c) Al-Hilal</td><td>3. M. K. Gandhi</td></tr><tr><td>(d) The Bengalee</td><td>4. B. G. Tilak</td></tr></table>', '<p>सूची-I (समाचार-पत्र) को सूची-II (संस्थापक/संपादक) से सुमेलित कीजिए:</p><table><tr><th>सूची-I</th><th>सूची-II</th></tr><tr><td>(a) केसरी</td><td>1. सुरेंद्रनाथ बनर्जी</td></tr><tr><td>(b) हरिजन</td><td>2. मौलाना अबुल कलाम आज़ाद</td></tr><tr><td>(c) अल-हिलाल</td><td>3. एम. के. गांधी</td></tr><tr><td>(d) द बंगाली</td><td>4. बी. जी. तिलक</td></tr></table>', '[{"key":"A","en":"a-4, b-3, c-2, d-1","hi":"a-4, b-3, c-2, d-1"},{"key":"B","en":"a-3, b-4, c-1, d-2","hi":"a-3, b-4, c-1, d-2"},{"key":"C","en":"a-4, b-2, c-3, d-1","hi":"a-4, b-2, c-3, d-1"},{"key":"D","en":"a-1, b-3, c-2, d-4","hi":"a-1, b-3, c-2, d-4"},{"key":"E","en":"None of the above","hi":"उपर्युक्त में से कोई नहीं"}]'::jsonb, 'A', '<p><b>Correct: (A) a-4, b-3, c-2, d-1.</b></p><p>Kesari (Marathi, 1881) — Tilak; Harijan (1933) — Gandhi; Al-Hilal (Urdu, 1912) — Abul Kalam Azad; The Bengalee — Surendranath Banerjee. Every other code mismatches at least two pairs, so (E) is also wrong.</p>', '<p><b>सही उत्तर: (A) a-4, b-3, c-2, d-1.</b></p><p>केसरी (मराठी, 1881) — तिलक; हरिजन (1933) — गांधी; अल-हिलाल (उर्दू, 1912) — अबुल कलाम आज़ाद; द बंगाली — सुरेंद्रनाथ बनर्जी। अन्य सभी कूट में कम से कम दो जोड़े गलत हैं, इसलिए (E) भी गलत है।</p>', false, false, 'press-national-movement', 'sample', null
from public.subjects s join public.topics t on t.subject_id = s.id and t.slug = 'modern'
left join public.exams e on e.short_name = '68th'
where s.slug = 'history';
insert into public.questions (exam_id, year, subject_id, topic_id, difficulty, question_en, question_hi, options, correct_option, solution_en, solution_hi, is_dropped, is_high_priority, theme, source, created_by)
select e.id, 2018, s.id, t.id, 'easy', 'Madhubani painting is traditionally associated with which cultural region of Bihar?', 'मधुबनी चित्रकला परंपरागत रूप से बिहार के किस सांस्कृतिक क्षेत्र से जुड़ी है?', '[{"key":"A","en":"Magadh","hi":"मगध"},{"key":"B","en":"Mithila","hi":"मिथिला"},{"key":"C","en":"Bhojpur","hi":"भोजपुर"},{"key":"D","en":"Anga","hi":"अंग"}]'::jsonb, 'B', '<p><b>Correct: (B) Mithila.</b> Madhubani (Mithila) painting received a GI tag in 2007; it was traditionally drawn by women on walls and floors.</p><p>(D) Anga (Bhagalpur region) is known for Manjusha art; (A) Magadh and (C) Bhojpur are not the home of Madhubani painting.</p>', '<p><b>सही उत्तर: (B) मिथिला।</b> मधुबनी (मिथिला) चित्रकला को 2007 में GI टैग मिला; परंपरागत रूप से महिलाएँ इसे दीवारों व फ़र्श पर बनाती थीं।</p><p>(D) अंग (भागलपुर क्षेत्र) मंजूषा कला के लिए प्रसिद्ध है; (A) मगध और (C) भोजपुर मधुबनी चित्रकला के मूल क्षेत्र नहीं हैं।</p>', false, false, 'bihar-folk-art', 'sample', null
from public.subjects s join public.topics t on t.subject_id = s.id and t.slug = 'art-culture'
left join public.exams e on e.short_name = '64th'
where s.slug = 'history';
insert into public.questions (exam_id, year, subject_id, topic_id, difficulty, question_en, question_hi, options, correct_option, solution_en, solution_hi, is_dropped, is_high_priority, theme, source, created_by)
select e.id, 2017, s.id, t.id, 'easy', 'Which river is known as the ''Sorrow of Bihar''?', 'किस नदी को ''बिहार का शोक'' कहा जाता है?', '[{"key":"A","en":"Gandak","hi":"गंडक"},{"key":"B","en":"Kosi","hi":"कोसी"},{"key":"C","en":"Son","hi":"सोन"},{"key":"D","en":"Bagmati","hi":"बागमती"}]'::jsonb, 'B', '<p><b>Correct: (B) Kosi.</b> It carries a very high silt load from the Himalayas and has shifted its course westward by more than 100 km over two centuries, causing frequent floods (e.g. Kusaha breach, 2008).</p><p>(A) Gandak and (D) Bagmati also flood, but the title belongs to the Kosi. (C) Son is a south-bank peninsular river.</p>', '<p><b>सही उत्तर: (B) कोसी।</b> यह हिमालय से भारी मात्रा में गाद लाती है और पिछले दो सौ वर्षों में 100 किमी से अधिक पश्चिम की ओर मार्ग बदल चुकी है, जिससे बार-बार बाढ़ आती है (जैसे कुसहा तटबंध टूटना, 2008)।</p><p>(A) गंडक और (D) बागमती में भी बाढ़ आती है, पर यह उपाधि कोसी की है। (C) सोन गंगा के दक्षिण से आने वाली प्रायद्वीपीय नदी है।</p>', false, true, 'kosi', 'sample', null
from public.subjects s join public.topics t on t.subject_id = s.id and t.slug = 'bihar'
left join public.exams e on e.short_name = '63rd'
where s.slug = 'geography';
insert into public.questions (exam_id, year, subject_id, topic_id, difficulty, question_en, question_hi, options, correct_option, solution_en, solution_hi, is_dropped, is_high_priority, theme, source, created_by)
select e.id, 2023, s.id, t.id, 'medium', 'The Kosi river enters Bihar from which country?', 'कोसी नदी किस देश से होकर बिहार में प्रवेश करती है?', '[{"key":"A","en":"Bhutan","hi":"भूटान"},{"key":"B","en":"Nepal","hi":"नेपाल"},{"key":"C","en":"Bangladesh","hi":"बांग्लादेश"},{"key":"D","en":"China (Tibet) directly","hi":"सीधे चीन (तिब्बत) से"},{"key":"E","en":"More than one of the above","hi":"उपर्युक्त में से एक से अधिक"}]'::jsonb, 'B', '<p><b>Correct: (B) Nepal.</b> The Kosi (Sapta Kosi) is formed in Nepal by seven Himalayan streams (its headwaters such as the Arun rise in Tibet) and enters Bihar near Bhimnagar (Supaul district), close to the Kosi barrage on the India–Nepal border.</p><p>It does not flow through Bhutan or Bangladesh, and it does not enter Bihar directly from Tibet — so (A), (C), (D) and (E) are wrong.</p>', '<p><b>सही उत्तर: (B) नेपाल।</b> कोसी (सप्तकोसी) नेपाल में सात हिमालयी धाराओं से बनती है (अरुण जैसी उपधाराएँ तिब्बत से निकलती हैं) और भारत–नेपाल सीमा पर स्थित कोसी बराज के निकट भीमनगर (सुपौल ज़िला) के पास बिहार में प्रवेश करती है।</p><p>यह भूटान या बांग्लादेश से नहीं बहती और न ही सीधे तिब्बत से बिहार में आती है — अतः (A), (C), (D), (E) गलत हैं।</p>', false, false, 'kosi', 'sample', null
from public.subjects s join public.topics t on t.subject_id = s.id and t.slug = 'bihar'
left join public.exams e on e.short_name = '69th'
where s.slug = 'geography';
insert into public.questions (exam_id, year, subject_id, topic_id, difficulty, question_en, question_hi, options, correct_option, solution_en, solution_hi, is_dropped, is_high_priority, theme, source, created_by)
select e.id, 2019, s.id, t.id, 'easy', 'The ozone layer is found mainly in which layer of the atmosphere?', 'ओज़ोन परत मुख्य रूप से वायुमंडल की किस परत में पाई जाती है?', '[{"key":"A","en":"Troposphere","hi":"क्षोभमंडल"},{"key":"B","en":"Stratosphere","hi":"समतापमंडल"},{"key":"C","en":"Mesosphere","hi":"मध्यमंडल"},{"key":"D","en":"Thermosphere","hi":"तापमंडल"}]'::jsonb, 'B', '<p><b>Correct: (B) Stratosphere</b> — roughly 15–35 km above the surface; the ozone absorbs harmful UV-B radiation.</p><p>(A) The troposphere is where weather occurs. (C) Meteors burn up in the mesosphere. (D) The thermosphere contains the ionosphere, which reflects radio waves.</p>', '<p><b>सही उत्तर: (B) समतापमंडल</b> — सतह से लगभग 15–35 किमी ऊपर; ओज़ोन हानिकारक UV-B विकिरण को अवशोषित करती है।</p><p>(A) क्षोभमंडल में मौसम संबंधी घटनाएँ होती हैं। (C) उल्काएँ मध्यमंडल में जलती हैं। (D) तापमंडल में आयनमंडल है, जो रेडियो तरंगों को परावर्तित करता है।</p>', false, false, null, 'sample', null
from public.subjects s join public.topics t on t.subject_id = s.id and t.slug = 'physical'
left join public.exams e on e.short_name = '65th'
where s.slug = 'geography';
insert into public.questions (exam_id, year, subject_id, topic_id, difficulty, question_en, question_hi, options, correct_option, solution_en, solution_hi, is_dropped, is_high_priority, theme, source, created_by)
select e.id, 2022, s.id, t.id, 'medium', 'The Strait of Malacca separates:', 'मलक्का जलडमरूमध्य किन्हें अलग करता है?', '[{"key":"A","en":"India and Sri Lanka","hi":"भारत और श्रीलंका"},{"key":"B","en":"Malay Peninsula and Sumatra","hi":"मलय प्रायद्वीप और सुमात्रा"},{"key":"C","en":"Java and Sumatra","hi":"जावा और सुमात्रा"},{"key":"D","en":"Africa and Europe","hi":"अफ़्रीका और यूरोप"},{"key":"E","en":"None of the above","hi":"उपर्युक्त में से कोई नहीं"}]'::jsonb, 'B', '<p><b>Correct: (B)</b> The Strait of Malacca lies between the Malay Peninsula and the Indonesian island of Sumatra — one of the busiest shipping lanes linking the Indian and Pacific Oceans.</p><p>(A) India–Sri Lanka: Palk Strait. (C) Java–Sumatra: Sunda Strait. (D) Africa–Europe: Strait of Gibraltar.</p>', '<p><b>सही उत्तर: (B)</b> मलक्का जलडमरूमध्य मलय प्रायद्वीप और इंडोनेशिया के सुमात्रा द्वीप के बीच है — हिंद और प्रशांत महासागर को जोड़ने वाला व्यस्ततम समुद्री मार्ग।</p><p>(A) भारत–श्रीलंका: पाक जलडमरूमध्य। (C) जावा–सुमात्रा: सुंडा जलडमरूमध्य। (D) अफ़्रीका–यूरोप: जिब्राल्टर जलडमरूमध्य।</p>', false, false, null, 'sample', null
from public.subjects s join public.topics t on t.subject_id = s.id and t.slug = 'world'
left join public.exams e on e.short_name = '67th'
where s.slug = 'geography';
insert into public.questions (exam_id, year, subject_id, topic_id, difficulty, question_en, question_hi, options, correct_option, solution_en, solution_hi, is_dropped, is_high_priority, theme, source, created_by)
select e.id, 2022, s.id, t.id, 'easy', 'Which Article of the Indian Constitution abolishes untouchability?', 'भारतीय संविधान का कौन-सा अनुच्छेद अस्पृश्यता का उन्मूलन करता है?', '[{"key":"A","en":"Article 14","hi":"अनुच्छेद 14"},{"key":"B","en":"Article 15","hi":"अनुच्छेद 15"},{"key":"C","en":"Article 17","hi":"अनुच्छेद 17"},{"key":"D","en":"Article 21","hi":"अनुच्छेद 21"},{"key":"E","en":"More than one of the above","hi":"उपर्युक्त में से एक से अधिक"}]'::jsonb, 'C', '<p><b>Correct: (C) Article 17</b> abolishes untouchability and forbids its practice in any form; it is enforced through the Protection of Civil Rights Act, 1955.</p><p>(A) Art 14 — equality before law. (B) Art 15 — no discrimination on grounds of religion, race, caste, sex or place of birth. (D) Art 21 — life and personal liberty. Only one article is correct, so (E) is wrong.</p>', '<p><b>सही उत्तर: (C) अनुच्छेद 17</b> अस्पृश्यता का अंत करता है और किसी भी रूप में इसके आचरण को निषिद्ध करता है; इसे नागरिक अधिकार संरक्षण अधिनियम, 1955 द्वारा लागू किया जाता है।</p><p>(A) अनु. 14 — विधि के समक्ष समता। (B) अनु. 15 — धर्म, मूलवंश, जाति, लिंग या जन्मस्थान के आधार पर भेदभाव का निषेध। (D) अनु. 21 — प्राण एवं दैहिक स्वतंत्रता। केवल एक अनुच्छेद सही है, अतः (E) गलत है।</p>', false, false, 'fundamental-rights', 'sample', null
from public.subjects s join public.topics t on t.subject_id = s.id and t.slug = 'fundamental-rights'
left join public.exams e on e.short_name = '67th'
where s.slug = 'polity';
insert into public.questions (exam_id, year, subject_id, topic_id, difficulty, question_en, question_hi, options, correct_option, solution_en, solution_hi, is_dropped, is_high_priority, theme, source, created_by)
select e.id, 2018, s.id, t.id, 'easy', 'The words ''Socialist'' and ''Secular'' were added to the Preamble by which Constitutional Amendment?', '''समाजवादी'' और ''पंथनिरपेक्ष'' शब्द प्रस्तावना में किस संविधान संशोधन द्वारा जोड़े गए?', '[{"key":"A","en":"42nd Amendment","hi":"42वाँ संशोधन"},{"key":"B","en":"44th Amendment","hi":"44वाँ संशोधन"},{"key":"C","en":"24th Amendment","hi":"24वाँ संशोधन"},{"key":"D","en":"52nd Amendment","hi":"52वाँ संशोधन"}]'::jsonb, 'A', '<p><b>Correct: (A) 42nd Amendment Act, 1976</b> added ''Socialist'', ''Secular'' and ''Integrity''. It is the only amendment to the Preamble so far.</p><p>(B) 44th (1978) removed the right to property from Fundamental Rights. (C) 24th (1971) affirmed Parliament''s power to amend Fundamental Rights. (D) 52nd (1985) added the Anti-Defection law (Tenth Schedule).</p>', '<p><b>सही उत्तर: (A) 42वाँ संशोधन अधिनियम, 1976</b> — इसने ''समाजवादी'', ''पंथनिरपेक्ष'' और ''अखंडता'' शब्द जोड़े। प्रस्तावना में अब तक यही एकमात्र संशोधन है।</p><p>(B) 44वें (1978) ने संपत्ति के अधिकार को मौलिक अधिकारों से हटाया। (C) 24वें (1971) ने मौलिक अधिकारों में संशोधन की संसद की शक्ति की पुष्टि की। (D) 52वें (1985) ने दल-बदल विरोधी कानून (दसवीं अनुसूची) जोड़ा।</p>', false, false, 'preamble', 'sample', null
from public.subjects s join public.topics t on t.subject_id = s.id and t.slug = 'constitution'
left join public.exams e on e.short_name = '64th'
where s.slug = 'polity';
insert into public.questions (exam_id, year, subject_id, topic_id, difficulty, question_en, question_hi, options, correct_option, solution_en, solution_hi, is_dropped, is_high_priority, theme, source, created_by)
select e.id, 2023, s.id, t.id, 'medium', '<p>Consider the following statements:</p><ol><li>The 73rd Constitutional Amendment Act added Part IX to the Constitution.</li><li>Bihar was the first state to provide 50% reservation for women in Panchayati Raj Institutions.</li></ol><p>Which of the statements given above is/are correct?</p>', '<p>निम्नलिखित कथनों पर विचार कीजिए:</p><ol><li>73वें संविधान संशोधन अधिनियम ने संविधान में भाग IX जोड़ा।</li><li>पंचायती राज संस्थाओं में महिलाओं को 50% आरक्षण देने वाला बिहार पहला राज्य था।</li></ol><p>उपर्युक्त में से कौन-सा/से कथन सही है/हैं?</p>', '[{"key":"A","en":"1 only","hi":"केवल 1"},{"key":"B","en":"2 only","hi":"केवल 2"},{"key":"C","en":"Both 1 and 2","hi":"1 और 2 दोनों"},{"key":"D","en":"Neither 1 nor 2","hi":"न तो 1 और न ही 2"}]'::jsonb, 'C', '<p><b>Correct: (C) Both.</b> Statement 1: the 73rd Amendment (1992) added Part IX (''The Panchayats'', Art 243–243O) and the Eleventh Schedule. Statement 2: Bihar''s Panchayat Raj Act, 2006 made it the first state to reserve 50% of panchayat seats for women.</p>', '<p><b>सही उत्तर: (C) दोनों।</b> कथन 1: 73वें संशोधन (1992) ने भाग IX (''पंचायतें'', अनु. 243–243O) तथा ग्यारहवीं अनुसूची जोड़ी। कथन 2: बिहार पंचायत राज अधिनियम, 2006 के ज़रिए बिहार पंचायतों में महिलाओं को 50% आरक्षण देने वाला पहला राज्य बना।</p>', false, false, 'panchayati-raj', 'sample', null
from public.subjects s join public.topics t on t.subject_id = s.id and t.slug = 'local-government'
