insert into public.questions (exam_id, year, subject_id, topic_id, difficulty, question_en, question_hi, options, correct_option, solution_en, solution_hi, is_dropped, is_high_priority, theme, source, created_by)
select e.id, 2020, s.id, t.id, 'medium', 'In which year was the Patna High Court established?', 'पटना उच्च न्यायालय की स्थापना किस वर्ष हुई?', '[{"key":"A","en":"1912","hi":"1912"},{"key":"B","en":"1916","hi":"1916"},{"key":"C","en":"1936","hi":"1936"},{"key":"D","en":"1950","hi":"1950"}]'::jsonb, 'B', '<p><b>Correct: (B) 1916.</b> The Patna High Court was inaugurated by Viceroy Lord Hardinge on 3 February 1916, four years after Bihar & Orissa were separated from Bengal.</p><p>(A) 1912 — Bihar & Orissa province created. (C) 1936 — Orissa became a separate province. (D) 1950 — the Constitution came into force.</p>', '<p><b>सही उत्तर: (B) 1916.</b> पटना उच्च न्यायालय का उद्घाटन वायसराय लॉर्ड हार्डिंग ने 3 फ़रवरी 1916 को किया, बंगाल से बिहार–उड़ीसा के अलग होने के चार वर्ष बाद।</p><p>(A) 1912 — बिहार व उड़ीसा प्रांत बना। (C) 1936 — उड़ीसा अलग प्रांत बना। (D) 1950 — संविधान लागू हुआ।</p>', false, false, null, 'sample', null
from public.subjects s join public.topics t on t.subject_id = s.id and t.slug = 'bihar-polity'
