insert into public.questions (exam_id, year, subject_id, topic_id, difficulty, question_en, question_hi, options, correct_option, solution_en, solution_hi, is_dropped, is_high_priority, theme, source, created_by)
select e.id, 2023, s.id, t.id, 'easy', 'The ''Repo Rate'' is the rate at which:', '''रेपो दर'' वह दर है जिस पर:', '[{"key":"A","en":"Commercial banks park surplus funds with the RBI","hi":"वाणिज्यिक बैंक अपनी अतिरिक्त राशि RBI के पास रखते हैं"},{"key":"B","en":"The RBI lends short-term funds to commercial banks against government securities","hi":"RBI सरकारी प्रतिभूतियों के बदले वाणिज्यिक बैंकों को अल्पकालिक ऋण देता है"},{"key":"C","en":"Commercial banks lend to their best customers","hi":"वाणिज्यिक बैंक अपने सर्वोत्तम ग्राहकों को ऋण देते हैं"},{"key":"D","en":"The government borrows from the public","hi":"सरकार जनता से उधार लेती है"}]'::jsonb, 'B', '<p><b>Correct: (B).</b> Under repo (repurchase agreement) the RBI lends to banks against securities, which banks repurchase later. A higher repo makes borrowing costlier and is used to curb inflation.</p><p>(A) describes the reverse repo / Standing Deposit Facility. (C) describes a bank''s lending rate (MCLR/prime rate). (D) describes government borrowing through bonds.</p>', '<p><b>सही उत्तर: (B)।</b> रेपो (पुनर्खरीद समझौता) के अंतर्गत RBI प्रतिभूतियों के बदले बैंकों को ऋण देता है, जिन्हें बैंक बाद में पुनः खरीदते हैं। रेपो बढ़ने से उधार महँगा होता है — यह मुद्रास्फीति नियंत्रण का उपाय है।</p><p>(A) रिवर्स रेपो / स्थायी जमा सुविधा (SDF) है। (C) बैंक की ऋण दर (MCLR/प्राइम रेट) है। (D) बॉन्ड के ज़रिए सरकारी उधारी है।</p>', false, false, 'monetary-policy', 'sample', null
from public.subjects s join public.topics t on t.subject_id = s.id and t.slug = 'banking'
