insert into public.questions (exam_id, year, subject_id, topic_id, difficulty, question_en, question_hi, options, correct_option, solution_en, solution_hi, is_dropped, is_high_priority, theme, source, created_by)
select e.id, 2019, s.id, t.id, 'medium', 'GDP at market price minus depreciation is equal to:', 'बाज़ार मूल्य पर GDP में से मूल्यह्रास घटाने पर क्या प्राप्त होता है?', '[{"key":"A","en":"GNP at market price","hi":"बाज़ार मूल्य पर GNP"},{"key":"B","en":"NDP at market price","hi":"बाज़ार मूल्य पर NDP"},{"key":"C","en":"NNP at factor cost","hi":"साधन लागत पर NNP"},{"key":"D","en":"GDP at factor cost","hi":"साधन लागत पर GDP"}]'::jsonb, 'B', '<p><b>Correct: (B) NDP<sub>MP</sub> = GDP<sub>MP</sub> − Depreciation.</b></p><p>(A) GNP = GDP + Net Factor Income from Abroad. (C) NNP<sub>FC</sub> = NNP<sub>MP</sub> − Net Indirect Taxes (national income). (D) GDP<sub>FC</sub> = GDP<sub>MP</sub> − Net Indirect Taxes.</p>', '<p><b>सही उत्तर: (B) NDP<sub>MP</sub> = GDP<sub>MP</sub> − मूल्यह्रास।</b></p><p>(A) GNP = GDP + विदेश से शुद्ध साधन आय। (C) NNP<sub>FC</sub> = NNP<sub>MP</sub> − शुद्ध अप्रत्यक्ष कर (राष्ट्रीय आय)। (D) GDP<sub>FC</sub> = GDP<sub>MP</sub> − शुद्ध अप्रत्यक्ष कर।</p>', false, false, null, 'sample', null
from public.subjects s join public.topics t on t.subject_id = s.id and t.slug = 'national-income'
