insert into public.questions (exam_id, year, subject_id, topic_id, difficulty, question_en, question_hi, options, correct_option, solution_en, solution_hi, is_dropped, is_high_priority, theme, source, created_by)
select e.id, 2024, s.id, t.id, 'medium', 'Fiscal deficit is defined as:', 'राजकोषीय घाटे की परिभाषा है:', '[{"key":"A","en":"Revenue expenditure − Revenue receipts","hi":"राजस्व व्यय − राजस्व प्राप्तियाँ"},{"key":"B","en":"Total expenditure − Total receipts excluding borrowings","hi":"कुल व्यय − उधार को छोड़कर कुल प्राप्तियाँ"},{"key":"C","en":"Fiscal deficit − Interest payments","hi":"राजकोषीय घाटा − ब्याज भुगतान"},{"key":"D","en":"Total expenditure − Revenue receipts","hi":"कुल व्यय − राजस्व प्राप्तियाँ"},{"key":"E","en":"More than one of the above","hi":"उपर्युक्त में से एक से अधिक"}]'::jsonb, 'B', '<p><b>Correct: (B).</b> Fiscal deficit = Total expenditure − (Revenue receipts + non-debt capital receipts); it equals the government''s total borrowing requirement.</p><p>(A) is Revenue deficit. (C) is Primary deficit. (D) ignores non-debt capital receipts (e.g. disinvestment, loan recoveries), so it is not the fiscal deficit.</p>', '<p><b>सही उत्तर: (B)।</b> राजकोषीय घाटा = कुल व्यय − (राजस्व प्राप्तियाँ + गैर-ऋण पूँजीगत प्राप्तियाँ); यह सरकार की कुल उधारी आवश्यकता के बराबर है।</p><p>(A) राजस्व घाटा है। (C) प्राथमिक घाटा है। (D) में गैर-ऋण पूँजीगत प्राप्तियाँ (जैसे विनिवेश, ऋण वसूली) छूट जाती हैं, इसलिए यह राजकोषीय घाटा नहीं है।</p>', false, true, 'deficits', 'sample', null
from public.subjects s join public.topics t on t.subject_id = s.id and t.slug = 'fiscal-policy'
