insert into public.questions (exam_id, year, subject_id, topic_id, difficulty, question_en, question_hi, options, correct_option, solution_en, solution_hi, is_dropped, is_high_priority, theme, source, created_by)
select e.id, 2022, s.id, t.id, 'easy', '''Shahi Litchi'', which received a GI tag, is associated with which district of Bihar?', 'GI टैग प्राप्त ''शाही लीची'' बिहार के किस ज़िले से संबंधित है?', '[{"key":"A","en":"Muzaffarpur","hi":"मुज़फ़्फ़रपुर"},{"key":"B","en":"Bhagalpur","hi":"भागलपुर"},{"key":"C","en":"Gaya","hi":"गया"},{"key":"D","en":"Darbhanga","hi":"दरभंगा"},{"key":"E","en":"None of the above","hi":"उपर्युक्त में से कोई नहीं"}]'::jsonb, 'A', '<p><b>Correct: (A) Muzaffarpur.</b> Shahi Litchi of Muzaffarpur got its GI tag in 2018.</p><p>(B) Bhagalpur is known for Jardalu mango and Bhagalpuri silk. (C) Gaya is known for Tilkut. (D) Darbhanga is famous for Makhana, which is marketed as ''Mithila Makhana'' (GI 2022).</p>', '<p><b>सही उत्तर: (A) मुज़फ़्फ़रपुर।</b> मुज़फ़्फ़रपुर की शाही लीची को 2018 में GI टैग मिला।</p><p>(B) भागलपुर जर्दालु आम व भागलपुरी सिल्क के लिए प्रसिद्ध है। (C) गया तिलकुट के लिए। (D) दरभंगा मखाना के लिए प्रसिद्ध है, जिसे ''मिथिला मखाना'' (GI 2022) कहा जाता है।</p>', false, false, 'gi-tags', 'sample', null
