insert into public.questions (exam_id, year, subject_id, topic_id, difficulty, question_en, question_hi, options, correct_option, solution_en, solution_hi, is_dropped, is_high_priority, theme, source, created_by)
select e.id, 2017, s.id, t.id, 'easy', 'What is the chemical formula of baking soda?', 'खाने के सोडा (बेकिंग सोडा) का रासायनिक सूत्र क्या है?', '[{"key":"A","en":"Na<sub>2</sub>CO<sub>3</sub>","hi":"Na<sub>2</sub>CO<sub>3</sub>"},{"key":"B","en":"NaHCO<sub>3</sub>","hi":"NaHCO<sub>3</sub>"},{"key":"C","en":"NaOH","hi":"NaOH"},{"key":"D","en":"CaCO<sub>3</sub>","hi":"CaCO<sub>3</sub>"}]'::jsonb, 'B', '<p><b>Correct: (B) NaHCO<sub>3</sub></b> — sodium hydrogen carbonate (sodium bicarbonate). On heating it releases CO<sub>2</sub>, which makes dough rise.</p><p>(A) Na<sub>2</sub>CO<sub>3</sub> is washing soda (as decahydrate). (C) NaOH is caustic soda. (D) CaCO<sub>3</sub> is limestone/chalk/marble.</p>', '<p><b>सही उत्तर: (B) NaHCO<sub>3</sub></b> — सोडियम हाइड्रोजन कार्बोनेट (सोडियम बाइकार्बोनेट)। गर्म करने पर यह CO<sub>2</sub> छोड़ता है, जिससे आटा फूलता है।</p><p>(A) Na<sub>2</sub>CO<sub>3</sub> धोने का सोडा (डेकाहाइड्रेट रूप में) है। (C) NaOH कास्टिक सोडा है। (D) CaCO<sub>3</sub> चूना-पत्थर/खड़िया/संगमरमर है।</p>', false, false, null, 'sample', null
from public.subjects s join public.topics t on t.subject_id = s.id and t.slug = 'chemistry'
