insert into public.questions (exam_id, year, subject_id, topic_id, difficulty, question_en, question_hi, options, correct_option, solution_en, solution_hi, is_dropped, is_high_priority, theme, source, created_by)
select e.id, 2023, s.id, t.id, 'easy', 'Deficiency of Vitamin C causes:', 'विटामिन C की कमी से कौन-सा रोग होता है?', '[{"key":"A","en":"Rickets","hi":"रिकेट्स (सूखा रोग)"},{"key":"B","en":"Scurvy","hi":"स्कर्वी"},{"key":"C","en":"Beriberi","hi":"बेरीबेरी"},{"key":"D","en":"Night blindness","hi":"रतौंधी"},{"key":"E","en":"More than one of the above","hi":"उपर्युक्त में से एक से अधिक"}]'::jsonb, 'B', '<p><b>Correct: (B) Scurvy</b> — bleeding gums and poor wound healing, because vitamin C (ascorbic acid) is needed for collagen synthesis.</p><p>(A) Rickets — vitamin D. (C) Beriberi — vitamin B1 (thiamine). (D) Night blindness — vitamin A. Only one disease matches, so (E) is wrong.</p>', '<p><b>सही उत्तर: (B) स्कर्वी</b> — मसूड़ों से रक्तस्राव और घाव देर से भरना, क्योंकि कोलेजन निर्माण के लिए विटामिन C (एस्कॉर्बिक अम्ल) आवश्यक है।</p><p>(A) रिकेट्स — विटामिन D। (C) बेरीबेरी — विटामिन B1 (थायमिन)। (D) रतौंधी — विटामिन A। केवल एक रोग मेल खाता है, अतः (E) गलत है।</p>', false, false, 'vitamins', 'sample', null
from public.subjects s join public.topics t on t.subject_id = s.id and t.slug = 'biology'
