insert into public.questions (exam_id, year, subject_id, topic_id, difficulty, question_en, question_hi, options, correct_option, solution_en, solution_hi, is_dropped, is_high_priority, theme, source, created_by)
select e.id, 2018, s.id, t.id, 'easy', 'People with which blood group are called ''universal donors''?', 'किस रक्त समूह वाले व्यक्तियों को ''सर्वदाता'' कहा जाता है?', '[{"key":"A","en":"A","hi":"A"},{"key":"B","en":"B","hi":"B"},{"key":"C","en":"AB","hi":"AB"},{"key":"D","en":"O","hi":"O"}]'::jsonb, 'D', '<p><b>Correct: (D) O</b> (specifically O-negative) — its red cells carry no A or B antigens, so they are not attacked by anti-A/anti-B antibodies in the recipient.</p><p>(C) AB is the universal recipient because its plasma has no anti-A or anti-B antibodies. (A) and (B) can donate only to matching/AB groups.</p>', '<p><b>सही उत्तर: (D) O</b> (विशेषकर O-नेगेटिव) — इसकी लाल रक्त कोशिकाओं पर A या B प्रतिजन नहीं होते, अतः प्राप्तकर्ता के एंटी-A/एंटी-B प्रतिरक्षी उन पर आक्रमण नहीं करते।</p><p>(C) AB सर्वग्राही है, क्योंकि इसके प्लाज़्मा में एंटी-A या एंटी-B प्रतिरक्षी नहीं होते। (A) व (B) केवल समान/AB समूह को रक्त दे सकते हैं।</p>', false, false, 'blood-groups', 'sample', null
from public.subjects s join public.topics t on t.subject_id = s.id and t.slug = 'biology'
