where s.slug = 'science';
insert into public.questions (exam_id, year, subject_id, topic_id, difficulty, question_en, question_hi, options, correct_option, solution_en, solution_hi, is_dropped, is_high_priority, theme, source, created_by)
select e.id, 2023, s.id, t.id, 'easy', 'The G20 Leaders'' Summit held under India''s presidency in September 2023 took place in:', 'भारत की अध्यक्षता में सितंबर 2023 में आयोजित G20 शिखर सम्मेलन कहाँ हुआ?', '[{"key":"A","en":"Mumbai","hi":"मुंबई"},{"key":"B","en":"New Delhi","hi":"नई दिल्ली"},{"key":"C","en":"Bengaluru","hi":"बेंगलुरु"},{"key":"D","en":"Hyderabad","hi":"हैदराबाद"},{"key":"E","en":"None of the above","hi":"उपर्युक्त में से कोई नहीं"}]'::jsonb, 'B', '<p><b>Correct: (B) New Delhi</b>, at the Bharat Mandapam (9–10 September 2023). The African Union was admitted as a permanent member at this summit; the theme was ''Vasudhaiva Kutumbakam — One Earth, One Family, One Future''.</p><p>Mumbai, Bengaluru and Hyderabad hosted ministerial/working-group meetings during the presidency, not the leaders'' summit.</p>', '<p><b>सही उत्तर: (B) नई दिल्ली</b>, भारत मंडपम में (9–10 सितंबर 2023)। इसी सम्मेलन में अफ़्रीकी संघ को स्थायी सदस्य बनाया गया; थीम थी ''वसुधैव कुटुम्बकम् — एक पृथ्वी, एक परिवार, एक भविष्य''।</p><p>मुंबई, बेंगलुरु और हैदराबाद में अध्यक्षता के दौरान मंत्रिस्तरीय/कार्य-समूह बैठकें हुईं, शिखर सम्मेलन नहीं।</p>', false, false, 'g20', 'sample', null
from public.subjects s join public.topics t on t.subject_id = s.id and t.slug = 'international'
left join public.exams e on e.short_name = '69th'
