insert into public.questions (exam_id, year, subject_id, topic_id, difficulty, question_en, question_hi, options, correct_option, solution_en, solution_hi, is_dropped, is_high_priority, theme, source, created_by)
select e.id, 2024, s.id, t.id, 'medium', 'India observes ''National Space Day'' on which date, marking the Chandrayaan-3 landing?', 'चंद्रयान-3 की लैंडिंग की स्मृति में भारत ''राष्ट्रीय अंतरिक्ष दिवस'' किस तिथि को मनाता है?', '[{"key":"A","en":"23 August","hi":"23 अगस्त"},{"key":"B","en":"15 August","hi":"15 अगस्त"},{"key":"C","en":"14 July","hi":"14 जुलाई"},{"key":"D","en":"28 February","hi":"28 फ़रवरी"}]'::jsonb, 'A', '<p><b>Correct: (A) 23 August.</b> Chandrayaan-3''s Vikram lander touched down near the lunar south pole on 23 August 2023; the landing site was named ''Shiv Shakti Point''.</p><p>(C) 14 July 2023 was Chandrayaan-3''s launch date. (D) 28 February is National Science Day (Raman Effect). (B) is Independence Day.</p>', '<p><b>सही उत्तर: (A) 23 अगस्त।</b> चंद्रयान-3 का विक्रम लैंडर 23 अगस्त 2023 को चंद्रमा के दक्षिणी ध्रुव के पास उतरा; लैंडिंग स्थल का नाम ''शिव शक्ति पॉइंट'' रखा गया।</p><p>(C) 14 जुलाई 2023 चंद्रयान-3 के प्रक्षेपण की तिथि थी। (D) 28 फ़रवरी राष्ट्रीय विज्ञान दिवस (रमन प्रभाव) है। (B) स्वतंत्रता दिवस है।</p>', false, false, 'chandrayaan', 'sample', null
