insert into public.questions (exam_id, year, subject_id, topic_id, difficulty, question_en, question_hi, options, correct_option, solution_en, solution_hi, is_dropped, is_high_priority, theme, source, created_by)
select e.id, 2019, s.id, t.id, 'easy', 'Bihar Diwas (Bihar Day) is celebrated every year on:', 'बिहार दिवस प्रतिवर्ष किस तिथि को मनाया जाता है?', '[{"key":"A","en":"22 March","hi":"22 मार्च"},{"key":"B","en":"26 January","hi":"26 जनवरी"},{"key":"C","en":"15 November","hi":"15 नवंबर"},{"key":"D","en":"1 April","hi":"1 अप्रैल"}]'::jsonb, 'A', '<p><b>Correct: (A) 22 March</b> — on this day in 1912, Bihar (with Orissa) was carved out of the Bengal Presidency.</p><p>(C) 15 November 2000 — Jharkhand was formed from Bihar. (D) 1 April 1936 — Orissa became a separate province. (B) is Republic Day.</p>', '<p><b>सही उत्तर: (A) 22 मार्च</b> — 1912 में इसी दिन बिहार (उड़ीसा सहित) को बंगाल प्रेसिडेंसी से अलग किया गया था।</p><p>(C) 15 नवंबर 2000 — बिहार से झारखंड बना। (D) 1 अप्रैल 1936 — उड़ीसा अलग प्रांत बना। (B) गणतंत्र दिवस है।</p>', false, false, 'bihar-diwas', 'sample', null
from public.subjects s join public.topics t on t.subject_id = s.id and t.slug = 'bihar-culture'
