insert into public.questions (exam_id, year, subject_id, topic_id, difficulty, question_en, question_hi, options, correct_option, solution_en, solution_hi, is_dropped, is_high_priority, theme, source, created_by)
select e.id, 2023, s.id, t.id, 'easy', '''Har Ghar Nal Ka Jal'' is a component of which Bihar government initiative?', '''हर घर नल का जल'' बिहार सरकार की किस पहल का घटक है?', '[{"key":"A","en":"Saat Nischay","hi":"सात निश्चय"},{"key":"B","en":"Jal-Jeevan-Hariyali","hi":"जल-जीवन-हरियाली"},{"key":"C","en":"Mukhyamantri Kanya Utthan Yojana","hi":"मुख्यमंत्री कन्या उत्थान योजना"},{"key":"D","en":"Kushal Yuva Program","hi":"कुशल युवा कार्यक्रम"}]'::jsonb, 'A', '<p><b>Correct: (A) Saat Nischay</b> (Seven Resolves, 2015). Its components include Har Ghar Nal Ka Jal, Har Ghar Bijli, Ghar Tak Pakki Gali-Naliyan, Shauchalay Nirman, Aarakshit Rozgar Mahilaon ka Adhikar, Aarthik Hal Yuvaon ko Bal and Avsar Badhe Aage Padhe.</p><p>(B) Jal-Jeevan-Hariyali (2019) is about water conservation and greenery. (C) is a girls'' education/incentive scheme. (D) Kushal Yuva Program is itself part of ''Aarthik Hal, Yuvaon ko Bal'' under Saat Nischay.</p>', '<p><b>सही उत्तर: (A) सात निश्चय</b> (2015)। इसके घटक हैं — हर घर नल का जल, हर घर बिजली, घर तक पक्की गली-नालियाँ, शौचालय निर्माण, आरक्षित रोज़गार महिलाओं का अधिकार, आर्थिक हल युवाओं को बल तथा अवसर बढ़े आगे पढ़ें।</p><p>(B) जल-जीवन-हरियाली (2019) जल संरक्षण व हरियाली से संबंधित है। (C) बालिका शिक्षा/प्रोत्साहन योजना है। (D) कुशल युवा कार्यक्रम स्वयं सात निश्चय के ''आर्थिक हल, युवाओं को बल'' का भाग है।</p>', false, false, 'saat-nischay', 'sample', null
from public.subjects s join public.topics t on t.subject_id = s.id and t.slug = 'bihar-schemes'
