select e.id, 2020, s.id, t.id, 'medium', 'Which is the longest river flowing within Bihar?', 'बिहार में बहने वाली सबसे लंबी नदी कौन-सी है?', '[{"key":"A","en":"Ganga","hi":"गंगा"},{"key":"B","en":"Ghaghara","hi":"घाघरा"},{"key":"C","en":"Gandak","hi":"गंडक"},{"key":"D","en":"Kosi","hi":"कोसी"}]'::jsonb, 'A', '<p><i>Sample dropped question:</i> ambiguous wording (total length vs. length within the state) — the kind of question BPSC cancels. It is kept for record but excluded from all quizzes.</p>', '<p><i>नमूना निरस्त प्रश्न:</i> अस्पष्ट शब्दावली (कुल लंबाई बनाम राज्य के भीतर लंबाई) — ऐसे प्रश्न BPSC रद्द करता है। यह रिकॉर्ड में है पर किसी क्विज़ में नहीं आता।</p>', true, false, null, 'sample', null
